-- Fastest Labs: its own email list, separate from Clinics, plus the bounced Fastest Labs addresses on Do not send.
-- Data: HubSpot export of Fastest Labs location contacts (2026-11-24, 3150 addresses, labb.com staff left out)
-- and the HubSpot bounce list (888 addresses).

-- Lists and audiences
alter table contact_imports drop constraint if exists contact_imports_list_check;
alter table contact_imports add constraint contact_imports_list_check check (list in ('employers', 'clinics', 'treatment', 'corrections', 'clinic-locations', 'fastest-labs'));
do $$ declare c text; begin
  for c in select conname from pg_constraint where conrelid = 'email_campaigns'::regclass and contype = 'c' and pg_get_constraintdef(oid) like '%audience%'
  loop execute format('alter table email_campaigns drop constraint %I', c); end loop;
  for c in select conname from pg_constraint where conrelid = 'email_suppressions'::regclass and contype = 'c' and pg_get_constraintdef(oid) like '%audience%'
  loop execute format('alter table email_suppressions drop constraint %I', c); end loop;
end $$;
alter table email_campaigns add constraint email_campaigns_audience_check check (audience in ('cpp', 'employers', 'clinics', 'treatment', 'corrections', 'newsletter', 'fastest-labs', 'clinics-all'));
alter table email_suppressions add constraint email_suppressions_audience_check check (audience in ('cpp', 'employers', 'clinics', 'treatment', 'corrections', 'newsletter', 'sequences', 'all', 'fastest-labs', 'clinics-all'));
-- Why an address is blocked: unsubscribed, added by an admin, or bounced.
alter table email_suppressions add column if not exists reason text;

create temporary table fl_contacts (email text, first_name text, last_name text, phone text) on commit drop;
