do $$
declare moved int; added int; switched int; total int; in_system int; blocked int; already int;
begin
  -- Fastest Labs contacts already on the Clinics list move to the new list.
  update contact_imports set list = 'fastest-labs', updated_at = now()
  where list = 'clinics' and (lower(email) like '%@fastestlabs.com' or lower(coalesce(company, '')) like '%fastest lab%'
    or lower(email) in (select email from fl_contacts));
  get diagnostics moved = row_count;
  -- Waiting in To sort: put them on the list.
  update contact_imports set list = 'fastest-labs', status = 'assigned', assigned_at = coalesce(assigned_at, now()), updated_at = now()
  where status = 'pending' and lower(email) in (select email from fl_contacts);
  get diagnostics switched = row_count;
  select count(*) into total from fl_contacts;
  insert into contact_imports (email, first_name, last_name, company, phone, source, batch, list, status, assigned_at)
  select f.email, f.first_name, f.last_name, 'Fastest Labs', f.phone, 'hubspot', 'HubSpot Fastest Labs locations (2026-11-24)', 'fastest-labs', 'assigned', now()
  from fl_contacts f where not exists (select 1 from contact_imports c where lower(c.email) = f.email);
  get diagnostics added = row_count;
  raise notice '[fastest-labs] % in file; % added; % moved from Clinics; % moved from To sort', total, added, moved, switched;

  -- Bounced addresses: on Do not send (every list) with the reason "bounced".
  select count(*) into in_system from fl_bounced b
  where exists (select 1 from contact_imports c where lower(c.email) = b.email) or exists (select 1 from leads l where lower(l.email) = b.email)
    or exists (select 1 from members m where lower(m.email) = b.email);
  select count(*) into already from fl_bounced b where exists (select 1 from email_suppressions s where s.email = b.email and s.audience = 'all');
  insert into email_suppressions (email, audience, reason) select email, 'all', 'bounced' from fl_bounced
  on conflict (email, audience) do update set reason = 'bounced';
  get diagnostics blocked = row_count;
  raise notice '[fastest-labs bounced] % in file; % were in the system; % were already on Do not send; % now on Do not send as bounced', (select count(*) from fl_bounced), in_system, already, blocked;
end $$;
